// Stage56 controlled public 44.1->48k constructor-parameter diagnostic.
// Reads only the verified first 2680 f64 from the built-in Sonicake WAV.
// Compiles against pinned MIT r8brain; generated bytes remain PRIVATE.
#include "CDSPResampler.h"
#include <cmath>
#include <cstdint>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>

int main(int argc, char** argv) {
    try {
        if (argc != 6) {
            std::cerr << "usage: public_forward_variant IN2680.f64 OUT.f64 TRANSBAND ATTEN PHASE(0|1)\n";
            return 2;
        }
        const double trans = std::stod(argv[3]);
        const double atten = std::stod(argv[4]);
        const int phase = std::stoi(argv[5]);
        if (!std::isfinite(trans) || trans < 0.5 || trans > 5.0 ||
            !std::isfinite(atten) || atten < 80.0 || atten > 240.0 ||
            (phase != 0 && phase != 1))
            throw std::runtime_error("invalid public constructor hypothesis");
        std::ifstream file(argv[1], std::ios::binary | std::ios::ate);
        if (!file || file.tellg() != static_cast<std::streamoff>(2680*8))
            throw std::runtime_error("2680 f64 expected");
        file.seekg(0);
        std::vector<double> input(2680);
        file.read(reinterpret_cast<char*>(input.data()), 2680*8);
        if (!file) throw std::runtime_error("private input read failed");
        for (double x: input)
            if (!std::isfinite(x)) throw std::runtime_error("nonfinite native input");
        const auto phase_kind = phase == 0 ? r8b::fprLinearPhase : r8b::fprMinPhase;
        r8b::CDSPResampler res(44100.0, 48000.0, 2680, trans, atten, phase_kind);
        double* out = nullptr;
        int count = res.process(input.data(), 2680, out);
        if (count < 0 || count > 50000 || (count > 0 && !out))
            throw std::runtime_error("public process count/pointer invalid");
        std::ofstream binary(argv[2], std::ios::binary);
        if (!binary) throw std::runtime_error("failed to create local output");
        if (count) {
            for (int i=0; i<count; ++i)
                if (!std::isfinite(out[i]))
                    throw std::runtime_error("nonfinite public output");
            binary.write(reinterpret_cast<const char*>(out), static_cast<std::streamsize>(count*8));
        }
        if (!binary) throw std::runtime_error("public output write failed");
        std::cout << "{\"output_f64\":" << count
                  << ",\"transband_percent\":" << trans
                  << ",\"attenuation_db\":" << atten
                  << ",\"phase\":" << phase
                  << ",\"latency\":" << res.getLatency()
                  << ",\"latency_frac\":" << std::setprecision(17)
                  << res.getLatencyFrac() << "}\n";
        return 0;
    } catch (const std::exception& e) {
        std::cerr << "[ERROR] " << e.what() << "\n";
        return 1;
    }
}
